// proxy.ts
import { NextResponse } from 'next/server'
import type { NextRequest } from 'next/server'
import { auth } from '@/auth'
import createIntlMiddleware from 'next-intl/middleware'
import { locales, defaultLocale } from '@/i18n-config'

const intlMiddleware = createIntlMiddleware({
  locales,
  defaultLocale,
  localePrefix: 'always',
})

const publicPaths = [
  '/',
  '/login',
  '/register',
  '/about',
  '/pricing',
  '/api/auth',
]

const adminPaths = ['/admin']

function isPublicPath(pathname: string): boolean {
  const pathWithoutLocale = pathname.replace(
    /^\/(en|uk|ru)/,
    ''
  ) || '/'
  return publicPaths.some(p => pathWithoutLocale.startsWith(p))
}

function isAdminPath(pathname: string): boolean {
  const pathWithoutLocale = pathname.replace(
    /^\/(en|uk|ru)/,
    ''
  ) || '/'
  return adminPaths.some(p => pathWithoutLocale.startsWith(p))
}

export default async function proxy(request: NextRequest) {
  const { pathname } = request.nextUrl

  // Skip static files and API auth routes
  if (
    pathname.startsWith('/_next') ||
    pathname.startsWith('/api/auth') ||
    pathname.includes('.')
  ) {
    return NextResponse.next()
  }

  // Apply i18n routing
  const intlResponse = intlMiddleware(request)

  // Public paths -- no auth check needed
  if (isPublicPath(pathname)) {
    return intlResponse
  }

  // Auth check for protected routes
  const session = await auth()

  if (!session?.user) {
    const locale = pathname.match(/^\/(en|uk|ru)/)?.[1] || defaultLocale
    const loginUrl = new URL(`/${locale}/login`, request.url)
    loginUrl.searchParams.set('callbackUrl', pathname)
    return NextResponse.redirect(loginUrl)
  }

  // Admin role check
  if (isAdminPath(pathname) && session.user.role !== 'ADMIN') {
    const locale = pathname.match(/^\/(en|uk|ru)/)?.[1] || defaultLocale
    return NextResponse.redirect(new URL(`/${locale}/unauthorized`, request.url))
  }

  return intlResponse
}

export const config = {
  matcher: ['/((?!_next|.*\\..*).*)'],
}

// app/(public)/[locale]/products/[id]/page.tsx
import type { Metadata } from 'next'

const locales = ['en', 'uk', 'ru'] as const
const baseUrl = 'https://ring-platform.org'

export async function generateMetadata({
  params,
}: {
  params: Promise<{ locale: string; id: string }>
}): Promise<Metadata> {
  const { locale, id } = await params
  const product = await getProduct(id, locale)

  if (!product) {
    return { title: 'Product Not Found' }
  }

  // Build hreflang alternates for all locales
  const alternates: Record<string, string> = {}
  for (const loc of locales) {
    alternates[loc] = `${baseUrl}/${loc}/products/${id}`
  }
  alternates['x-default'] = `${baseUrl}/en/products/${id}`

  return {
    title: `${product.name} | Ring Platform`,
    description: product.description,
    alternates: {
      canonical: `${baseUrl}/${locale}/products/${id}`,
      languages: alternates,
    },
    openGraph: {
      title: product.name,
      description: product.description,
      url: `${baseUrl}/${locale}/products/${id}`,
      siteName: 'Ring Platform',
      images: [
        {
          url: product.imageUrl,
          width: 1200,
          height: 630,
          alt: product.name,
        },
      ],
      locale: locale === 'uk' ? 'uk_UA' : locale === 'ru' ? 'ru_RU' : 'en_US',
      type: 'website',
    },
    twitter: {
      card: 'summary_large_image',
      title: product.name,
      description: product.description,
      images: [product.imageUrl],
    },
  }
}

