import { useEffect, useEffectEvent } from 'react'

function ChatRoom({ roomId, theme, onMessage }: {
  roomId: string
  theme: string
  onMessage: (msg: string) => void
}) {
  // Event handler that always sees latest props/state
  const onConnected = useEffectEvent(() => {
    showNotification(`Connected to ${roomId}!`, theme)
  })

  const onNewMessage = useEffectEvent((message: string) => {
    onMessage(message) // Always calls latest onMessage
  })

  useEffect(() => {
    const connection = createConnection(roomId)
    connection.on('connected', onConnected)
    connection.on('message', onNewMessage)
    connection.connect()
    return () => connection.disconnect()
  }, [roomId]) // theme and onMessage NOT in deps -- useEffectEvent handles it
}

