// app/(authenticated)/[locale]/posts/page.tsx
import { Suspense } from 'react'
import { auth } from '@/auth'
import { redirect } from 'next/navigation'
import { CreatePostForm } from './create-post-form'

export default async function PostsPage({
  params,
  searchParams,
}: {
  params: Promise<{ locale: string }>
  searchParams: Promise<{ page?: string; category?: string }>
}) {
  const { locale } = await params
  const { page = '1', category } = await searchParams
  const session = await auth()

  if (!session?.user) redirect(`/${locale}/login`)

  return (
    <div className="space-y-8">
      <div className="flex items-center justify-between">
        <h1 className="text-3xl font-bold">Posts</h1>
        <CreatePostForm locale={locale} />
      </div>

      <Suspense fallback={<PostGridSkeleton />}>
        <PostGrid
          locale={locale}
          page={Number(page)}
          category={category}
        />
      </Suspense>
    </div>
  )
}

// Cached component with tags for invalidation
async function PostGrid({
  locale,
  page,
  category,
}: {
  locale: string
  page: number
  category?: string
}) {
  'use cache'
  cacheTag('posts', category ? `category-${category}` : 'all-posts')
  cacheLife('minutes')

  const posts = await getPosts({ locale, page, category })
  return (
    <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
      {posts.map(post => (
        <PostCard key={post.id} post={post} locale={locale} />
      ))}
    </div>
  )
}

